css:
.quantum-grid {
  width: 100%;
  height: 100%;
  background: linear-gradient(
    135deg,
    rgba(0, 50, 100, 0.8),
    rgba(1, 103, 132, 0.8),
    rgba(0, 50, 100, 0.8)
  );
  filter: url(#quantum-texture);
  position: relative;
  overflow: hidden;
}

.depth-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: repeating-linear-gradient(
    45deg,
    transparent,
    transparent 20px,
    rgba(0, 255, 204, 0.15) 20px,
    rgba(0, 255, 204, 0.15) 40px
  );
}
